is_palindrome() {
  local str=${1,,}
  local len=${#str}
  for ((i=0; i<len/2; i++)); do
    if [ "${str:$i:1}" != "${str:$((len-1-i)):1}" ]; then
      return 1
    fi
  done
  return 0
}

is_palindrome "racecar" && echo "Palindrome" || echo "Not palindrome"

reverse_string() {
  local str=$1
  local reversed=""
  for ((i=${#str}-1; i>=0; i--)); do
    reversed+="${str:$i:1}"
  done
  echo "$reversed"
}

echo $(reverse_string "Hello")
